window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["inference-optimization"]={"title":"推理优化：先定位 prefill、decode、KV 还是排队瓶颈","subtitle":"从 TTFT/TPOT、算术强度和连续批处理，到 PagedAttention、FlashAttention、量化、推测解码与真实负载验收。","thesis":"LLM 服务不是一个统一瓶颈：输入 prefill 常偏计算密集，逐 token decode 常偏内存带宽，KV 容量限制并发，调度决定排队与尾延迟。优化必须先用真实负载定位主因，再以<b>质量、p95/p99、吞吐、显存和每成功任务成本</b>联合验收。","quality":{"contractVersion":2,"examples":[{"section":5,"evidence":{"setup":"退款助手启用大批处理后吞吐翻倍","rule":"调度参数必须按 SLO 而非峰值吞吐选择","steps":"平均 TTFT 520→470ms；p99 TTFT 1.8→3.2s","interpretation":"资源利用率改善不保证尾部体验"}}],"formulas":[{"id":"inference-latency","section":1,"formulaIndex":1,"symbols":[{"name":"TTFT","meaning":"请求到首 token 可见的时间","evidence":"TTFT 是请求到首 token 的时间"},{"name":"Q","meaning":"调度队列等待时间","evidence":"输入排队"},{"name":"Ccontext","meaning":"检索与上下文组装时间","evidence":"Ccontext 是上下文准备时间"},{"name":"Tprefill","meaning":"输入预填充耗时","evidence":"输入长度"},{"name":"Tfirst","meaning":"首个解码步耗时","evidence":"Tfirst 是首步解码时间"},{"name":"Tcomplete","meaning":"端到端完成时间","evidence":"端到端完成时间"},{"name":"N","meaning":"输出 token 总数","evidence":"N 是输出 token 总数"},{"name":"TPOT","meaning":"首 token 后平均每个 token 的时间","evidence":"TPOT 是首 token 后平均每个新 token 的时间"},{"name":"Texternal","meaning":"工具与传输等外部耗时","evidence":"工具与传输日志"}]},{"id":"inference-roofline","section":2,"formulaIndex":1,"symbols":[{"name":"AI","meaning":"每字节数据搬运对应的浮点运算量","evidence":"AI 是每搬运一字节完成的浮点运算数"},{"name":"FLOPs","meaning":"浮点运算次数","evidence":"每阶段 FLOPs"},{"name":"BytesIO","meaning":"内存读写字节数","evidence":"内存读写字节"},{"name":"Perfmax","meaning":"roofline 估算性能上限","evidence":"输出算术强度 AI 与 roofline 性能上限"},{"name":"ComputePeak","meaning":"硬件峰值计算吞吐","evidence":"峰值算力"},{"name":"Bandwidth","meaning":"硬件内存带宽","evidence":"内存带宽 Bandwidth"}]},{"id":"inference-kv-memory","section":4,"formulaIndex":1,"symbols":[{"name":"MKV","meaning":"KV 缓存总内存","evidence":"输出缓存内存 MKV"},{"name":"Nlayer","meaning":"模型层数","evidence":"层数 Nlayer"},{"name":"NKVhead","meaning":"每层 KV 头数","evidence":"KV 头数 NKVhead"},{"name":"d","meaning":"每个 KV 头的维度","evidence":"头维 d"},{"name":"Ntoken","meaning":"每请求缓存 token 数","evidence":"token 数 Ntoken"},{"name":"B","meaning":"并发请求数","evidence":"并发 B"},{"name":"b","meaning":"每个元素占用字节","evidence":"元素字节 b"}]},{"id":"inference-speculative-yield","section":8,"formulaIndex":1,"symbols":[{"name":"Edraft","meaning":"每轮期望确认的 token 数","evidence":"近似轮产出"},{"name":"a","meaning":"逐 token 接受率","evidence":"逐 token 接受率 a"},{"name":"k","meaning":"每轮草稿 token 数","evidence":"草稿长度 k"}]}],"termReviews":[{"term":"prefill","section":1,"evidence":"输入长度、输出长度"},{"term":"roofline","section":2,"evidence":"roofline 性能上限"},{"term":"连续批处理","section":3,"evidence":"连续批处理输入等待请求"},{"term":"推测解码","section":8,"evidence":"推测解码输入草稿模型"}],"sectionContracts":[{"section":1,"definition":{"answer":"推理阶段拆分把请求分成排队、prefill、decode 和外部耗时。","evidence":"先把端到端时间拆开"},"problem":{"answer":"它解释长输入短回答与短输入长回答为何需不同优化。","evidence":"为何需要不同优化"},"inputOutput":{"answer":"输入阶段日志和长度，输出 TTFT、TPOT 与完成时间。","evidence":"输出 TTFT、TPOT 和端到端完成时间"},"mechanism":{"answer":"先测排队和首 token，再累加后续 token 与外部耗时。","evidence":"TTFT 是请求到首 token 的时间"},"interpretation":{"answer":"不同指标分别指向输入、解码、排队或外部瓶颈。","evidence":"指标指向不同瓶颈"},"boundary":{"answer":"单一 tokens/s 不能代表交互用户体验。","evidence":"不能用单一 tokens/s 代表用户体验"}},{"section":2,"definition":{"answer":"算术强度描述每搬运一字节数据所完成的计算量。","evidence":"prefill 与 decode 的硬件性格不同"},"problem":{"answer":"它解释同一模型两阶段为何分别偏算力和偏带宽。","evidence":"一个吃算力、一个吃带宽"},"inputOutput":{"answer":"输入 FLOPs、字节、算力和带宽，输出 AI 与性能上限。","evidence":"输出算术强度 AI 与 roofline 性能上限"},"mechanism":{"answer":"性能上限取峰值算力和 AI 乘带宽中的较小者。","evidence":"上限取算力峰值与 AI×带宽中的较小者"},"interpretation":{"answer":"低 AI 更可能受带宽限制，高 AI 更可能受算力限制。","evidence":"每搬运一字节完成的浮点运算数"},"boundary":{"answer":"roofline 是定位直觉，不是具体内核的精确预测。","evidence":"不是每个内核的精确耗时预测"}},{"section":3,"definition":{"answer":"连续批处理在每个调度步动态移除完成序列并插入新请求。","evidence":"连续批处理用动态调度填掉空洞"},"problem":{"answer":"它减少静态批中短序列结束后留下的计算空槽。","evidence":"为什么 GPU 仍像在为它保留座位"},"inputOutput":{"answer":"输入队列、容量和优先级，输出插入、移除、分块或抢占。","evidence":"输出每个调度步的移除、插入、分块或抢占决定"},"mechanism":{"answer":"完成序列立即让位，新请求按容量和优先级进入。","evidence":"完成序列立刻让位给新请求"},"interpretation":{"answer":"吞吐上升不意味着 p99 和公平性同时改善。","evidence":"吞吐提高不代表尾延迟更好"},"boundary":{"answer":"过载必须有准入、背压和租户公平约束。","evidence":"必须有准入控制、背压和租户公平边界"}},{"section":4,"definition":{"answer":"KV 缓存为每个活跃 token 在每层保存 K 和 V。","evidence":"KV cache 是并发容量的隐藏预算"},"problem":{"answer":"它解释权重可放入显存但并发提高后仍会 OOM。","evidence":"为什么并发一上来仍 OOM"},"inputOutput":{"answer":"输入架构序列和并发规模，输出 KV 总内存。","evidence":"输出缓存内存 MKV"},"mechanism":{"answer":"层、头、维度、token、并发和字节相乘并因 K/V 乘二。","evidence":"K 与 V 各保存一次所以乘二"},"interpretation":{"answer":"估算值用于解释并发上限与显存不足。","evidence":"估算解释 OOM 和并发上限"},"boundary":{"answer":"分页只减碎片，量化或滑窗仍需质量回归。","evidence":"PagedAttention 只减少碎片"}},{"section":5,"definition":{"answer":"案例比较静态小批、激进连续批和分池分块三种调度。","evidence":"优化前后为何平均更快但 p99 更差"},"problem":{"answer":"它解释吞吐翻倍时交互用户仍可能投诉。","evidence":"交互用户为何投诉"},"inputOutput":{"answer":"输入方案与延迟吞吐指标，输出是否满足交互 SLO。","evidence":"输出是否满足交互 SLO 的选择"},"mechanism":{"answer":"先比较吞吐，再检查 TTFT 的中位数和尾部分位数。","evidence":"先比较吞吐，再检查 p50 与 p99"},"interpretation":{"answer":"平均更快但 p99 变差说明长输入或组批阻塞尾部。","evidence":"让 p99 失败"},"boundary":{"answer":"案例结论只适用于给定负载，变化后必须重测。","evidence":"负载变化必须重测"}},{"section":6,"definition":{"answer":"FlashAttention 以 IO 感知分块精确计算同一注意力。","evidence":"FlashAttention 减少 IO，不近似注意力结果"},"problem":{"answer":"它减少完整注意力中间矩阵反复往返 HBM。","evidence":"softmax 还能算得精确吗"},"inputOutput":{"answer":"输入相同 Q、K、V，输出相同结果和更少 HBM 往返。","evidence":"输出数值精度范围内相同的注意力结果和更少 HBM 往返"},"mechanism":{"answer":"分块装入片上存储并在线维护 softmax 统计量。","evidence":"通过分块和在线 softmax 改变计算顺序"},"interpretation":{"answer":"收益表示注意力 IO 降低，不代表所有服务瓶颈消失。","evidence":"不代表 KV 容量、排队或工具延迟得到解决"},"boundary":{"answer":"短序列或非注意力瓶颈场景可能没有收益。","evidence":"短序列和非注意力瓶颈可能无收益"}},{"section":7,"definition":{"answer":"量化用较低位宽表示权重、激活或 KV。","evidence":"量化减少字节，但属于质量相关改动"},"problem":{"answer":"它在显存和带宽受限时减少数据占用与搬运。","evidence":"为何既可能更快也可能更慢"},"inputOutput":{"answer":"输入对象位宽硬件和任务，输出速度显存及质量差异。","evidence":"输出低精度模型及显存、速度和质量差异"},"mechanism":{"answer":"低位宽节省存储带宽，但需要反量化和校准。","evidence":"反量化与校准又增加开销"},"interpretation":{"answer":"只有硬件支持和瓶颈匹配时才可能获得净加速。","evidence":"更快只在支持良好且瓶颈匹配时成立"},"boundary":{"answer":"必须覆盖语言、长上下文、工具参数和高风险任务。","evidence":"必须按语言、长上下文、工具参数和高风险任务回归"}},{"section":8,"definition":{"answer":"推测解码让草稿模型先提 token，再由目标模型批量验证。","evidence":"推测解码用并行验证减少串行步数"},"problem":{"answer":"它减少目标模型逐 token 串行前向的轮数。","evidence":"大模型怎样既加速又保持目标分布"},"inputOutput":{"answer":"输入草稿与目标模型、k 和 a，输出验证后的 token。","evidence":"输出经目标模型验证后的 token"},"mechanism":{"answer":"草稿并行提出，目标批量验证并按规则接受或校正。","evidence":"目标模型批量验证并按规则接受或校正"},"interpretation":{"answer":"近似产出随接受率和草稿长度提高，但还需扣除验证成本。","evidence":"近似轮产出是 1+a+…+a^k"},"boundary":{"answer":"低接受率或高验证成本会使推测解码变慢。","evidence":"低接受率或高验证成本会变慢"}},{"section":9,"definition":{"answer":"生产基准用真实负载联合验收性能、资源、质量和成本。","evidence":"真实负载基准和质量门禁缺一不可"},"problem":{"answer":"它判断离线单请求加速能否迁移到生产环境。","evidence":"怎样证明生产真的更好"},"inputOutput":{"answer":"输入真实负载与故障，输出分位延迟吞吐资源质量成本。","evidence":"输出延迟分位数、吞吐、资源、失败率、质量和每成功任务成本"},"mechanism":{"answer":"固定负载对照并覆盖稳态、突发、过载和节点故障。","evidence":"覆盖稳态、过载和节点故障"},"interpretation":{"answer":"平均 tokens/s 提升不能证明尾延迟和任务质量改善。","evidence":"只有平均 tokens/s 提升不能证明生产更好"},"boundary":{"answer":"算法和低精度变化都必须经过独立质量门禁。","evidence":"必须经过质量门禁"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分 TTFT、TPOT 和完成时间；识别计算/带宽/KV/排队瓶颈；推导批处理与推测解码收益；设计真实负载基准与回归门禁。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>先把端到端时间拆开<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">长输入短回答与短输入长回答，为何需要不同优化？</p><p>请求先排队，再 prefill 全部输入并建立 KV，随后每步 decode 一个 token，期间还可能检索、工具和传输。长输入主要增加 prefill 与 KV；长输出主要占用 decode 槽和权重/KV 读取。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"首 token 与完成时间分解\"><mi>TTFT</mi><mo>≈</mo><mi>Q</mi><mo>+</mo><mi>Ccontext</mi><mo>+</mo><mi>Tprefill</mi><mo>+</mo><mi>Tfirst</mi><mo>;</mo><mi>Tcomplete</mi><mo>≈</mo><mi>TTFT</mi><mo>+</mo><mo>(</mo><mi>N</mi><mo>−</mo><mn>1</mn><mo>)</mo><mo>×</mo><mi>TPOT</mi><mo>+</mo><mi>Texternal</mi></math></div><p>先按输入长度、输出长度、并发和缓存命中切片，否则“平均慢”无法指导是改内核、调度、缓存还是模型。</p><div class=\"dd-note\"><b>用户体验不是 tokens/s。</b>　交互场景重 TTFT/抖动，批处理离线任务更重吞吐和总成本。</div><p>阶段拆分输入排队、输入长度、输出长度、工具与传输日志，输出 TTFT、TPOT 和端到端完成时间。TTFT 是请求到首 token 的时间，Q 是排队时间，Ccontext 是上下文准备时间，Tprefill 是输入预填充时间，Tfirst 是首步解码时间；TPOT 是首 token 后平均每个新 token 的时间，N 是输出 token 总数，Texternal 是工具与传输时间。指标指向不同瓶颈，不能用单一 tokens/s 代表用户体验。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>prefill 与 decode 的硬件性格不同<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">为什么同一 Transformer 在两个阶段一个吃算力、一个吃带宽？</p><p>prefill 可并行处理许多输入 token，大矩阵乘法有较高算术强度，更容易利用 GPU compute；decode 每步 batch/token 维度小，要反复读取大权重和增长的 KV，常受 HBM 带宽限制。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"算术强度与 roofline 性能上限\"><mi>AI</mi><mo>=</mo><mfrac><mi>FLOPs</mi><mi>BytesIO</mi></mfrac><mo>;</mo><mi>Perfmax</mi><mo>≈</mo><mi>min</mi><mo>(</mo><mi>ComputePeak</mi><mo>,</mo><mi>AI</mi><mo>×</mo><mi>Bandwidth</mi><mo>)</mo></math></div><p>这是 roofline 直觉，不是每个内核的精确模型。批量增大可提升 decode 的权重复用，却会增加排队和 KV 压力；量化减少字节，FlashAttention 减少中间内存往返，分别瞄准不同瓶颈。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>阶段</th><th>主要工作</th><th>常见瓶颈</th><th>典型优化</th></tr></thead><tbody><tr><td>排队</td><td>等待调度</td><td>容量/批策略</td><td>扩容、优先级、背压</td></tr><tr><td>prefill</td><td>输入并行矩阵/注意力</td><td>算力、长序列 IO</td><td>FlashAttention、前缀缓存</td></tr><tr><td>decode</td><td>逐 token 权重/KV 读取</td><td>带宽、串行步数</td><td>批处理、量化、推测解码</td></tr><tr><td>工具</td><td>外部请求</td><td>网络/服务</td><td>并行、超时、缓存</td></tr></tbody></table></div><p>硬件瓶颈分析输入每阶段 FLOPs、内存读写字节 BytesIO、峰值算力 ComputePeak 和内存带宽 Bandwidth，输出算术强度 AI 与 roofline 性能上限 Perfmax。AI 是每搬运一字节完成的浮点运算数；上限取算力峰值与 AI×带宽中的较小者。它是定位直觉，不是每个内核的精确耗时预测。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>连续批处理用动态调度填掉空洞<span class=\"dd-badge eng\">调度</span></h2><p class=\"dd-lead\">静态批里短回答结束后，为什么 GPU 仍像在为它保留座位？</p><p>静态批等所有序列完成才换批，长度差异造成空槽。连续批处理在每个调度步移除已完成请求、插入新请求，提高利用率。代价是调度复杂、延迟波动和长短请求公平。</p><p>设置最大 batch token、prefill chunk、优先级和抢占；避免一个超长 prefill 阻塞所有 decode。交互与离线队列可分池，关键租户保留容量。组批等待越长吞吐可能越高，但 TTFT 也越差。</p><div class=\"dd-note warn\"><b>过载时优化器会变成放大器。</b>　无限队列让 GPU 始终满载却使 p99 失控；需要 admission control 和背压。</div><p>连续批处理输入等待请求、每步可用 token 容量和优先级，输出每个调度步的移除、插入、分块或抢占决定。完成序列立刻让位给新请求以减少空槽；吞吐提高不代表尾延迟更好。过载时必须有准入控制、背压和租户公平边界。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>KV cache 是并发容量的隐藏预算<span class=\"dd-badge math\">内存</span></h2><p class=\"dd-lead\">模型权重放得下，为什么并发一上来仍 OOM？</p><p>每个活跃 token 在每层保存 K/V，内存随并发和序列长度近似线性增长。粗略：</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"KV 缓存内存估算\"><mi>MKV</mi><mo>≈</mo><mn>2</mn><mo>×</mo><mi>Nlayer</mi><mo>×</mo><mi>NKVhead</mi><mo>×</mo><mi>d</mi><mo>×</mo><mi>Ntoken</mi><mo>×</mo><mi>B</mi><mo>×</mo><mi>b</mi></math></div><p>32 层、8 KV 头、128 维、FP16、每请求 8k token 时约 1.05GB/请求；16 个并发约 16.8GB，还未计权重与工作区。PagedAttention 用固定块减少外部碎片，支持前缀共享和更灵活驱逐，但不会消除 KV 本身。</p><p>KV 量化可减容量/带宽，却可能影响长上下文与质量；滑窗/压缩缓存会改变可见历史，应视作算法变化而非纯工程优化。</p><p>KV 容量估算输入层数 Nlayer、KV 头数 NKVhead、头维 d、token 数 Ntoken、并发 B 和元素字节 b，输出缓存内存 MKV。K 与 V 各保存一次所以乘二；估算解释 OOM 和并发上限，但 PagedAttention 只减少碎片，不会消除 KV 本体。量化或滑窗还需质量回归。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>运行示例：优化前后为何平均更快但 p99 更差<span class=\"dd-badge math\">案例推演</span></h2><p class=\"dd-lead\">退款助手启用大批处理后吞吐翻倍，交互用户为何投诉？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 710 260\" role=\"img\" aria-label=\"推理请求从队列经过 prefill 和 decode，批处理提高吞吐但可能增加尾延迟\"><defs><marker id=\"io1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"18\" y=\"90\" width=\"120\" height=\"70\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"78\" y=\"115\" text-anchor=\"middle\" class=\"svg-t\">请求队列</text><text x=\"78\" y=\"138\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">等待组批 0–400ms</text><path d=\"M138,125 L203,125\" stroke=\"#6b7484\" marker-end=\"url(#io1)\"/><rect x=\"205\" y=\"90\" width=\"140\" height=\"70\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"275\" y=\"115\" text-anchor=\"middle\" class=\"svg-t\">chunked prefill</text><text x=\"275\" y=\"138\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">长输入分块插空</text><path d=\"M345,125 L410,125\" stroke=\"#6b7484\" marker-end=\"url(#io1)\"/><rect x=\"412\" y=\"90\" width=\"140\" height=\"70\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"482\" y=\"115\" text-anchor=\"middle\" class=\"svg-t\">continuous decode</text><text x=\"482\" y=\"138\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">完成即插入新序列</text><path d=\"M552,125 L617,125\" stroke=\"#6b7484\" marker-end=\"url(#io1)\"/><rect x=\"619\" y=\"90\" width=\"74\" height=\"70\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"656\" y=\"115\" text-anchor=\"middle\" class=\"svg-t\">流式</text><text x=\"656\" y=\"138\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">delta</text><text x=\"355\" y=\"205\" text-anchor=\"middle\" class=\"svg-t\">吞吐 40→78 tok/s；平均 TTFT 520→470ms；p99 TTFT 1.8→3.2s（组批/长输入阻塞）</text></svg><figcaption>图 1　资源利用率改善不保证尾部体验；调度参数必须按 SLO 而非峰值吞吐选择。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>方案</th><th>吞吐</th><th>TTFT p50</th><th>TTFT p99</th><th>TPOT p95</th><th>结论</th></tr></thead><tbody><tr><td>静态小批</td><td>40 tok/s</td><td>520ms</td><td>1.8s</td><td>62ms</td><td>稳定但利用低</td></tr><tr><td>激进连续批</td><td>78 tok/s</td><td>470ms</td><td>3.2s</td><td>58ms</td><td>交互 SLO 失败</td></tr><tr><td>分池+chunk prefill</td><td>70 tok/s</td><td>430ms</td><td>1.6s</td><td>60ms</td><td>约束内更优</td></tr></tbody></table></div><p>调度案例输入三种组批策略及吞吐、TTFT 和 TPOT，输出是否满足交互 SLO 的选择。先比较吞吐，再检查 p50 与 p99；激进连续批虽然平均更快，却因组批和长输入阻塞让 p99 失败。结论只适用于该负载分布，负载变化必须重测。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>FlashAttention 减少 IO，不近似注意力结果<span class=\"dd-badge eng\">内核</span></h2><p class=\"dd-lead\">不保存完整 N×N 注意力矩阵，softmax 还能算得精确吗？</p><p>FlashAttention 将 Q/K/V 分块装入片上 SRAM，在线维护 softmax 的行最大值和归一化和，避免把巨大中间分数矩阵反复写回 HBM。算法在数值精度范围内计算同一注意力，而非稀疏近似。</p><p>收益随序列、硬件、dtype 和实现变化；短序列或其他算子主导时不显著。FlashAttention 不改变 KV 长期容量，也不会解决队列和工具延迟。升级内核要做数值、质量和稳定性回归。</p><div class=\"dd-note\"><b>优化匹配：</b>看到长 prefill 的注意力 IO 占主导才优先；若 p99 来自排队，换内核可能治标不治本。</div><p>FlashAttention 输入同一 Q、K、V 注意力计算，输出数值精度范围内相同的注意力结果和更少 HBM 往返。它通过分块和在线 softmax 改变计算顺序而非近似目标；收益表示注意力 IO 降低，不代表 KV 容量、排队或工具延迟得到解决。短序列和非注意力瓶颈可能无收益。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>量化减少字节，但属于质量相关改动<span class=\"dd-badge eng\">低精度</span></h2><p class=\"dd-lead\">把 FP16 权重改 INT4，为何既可能更快也可能更慢？</p><p>更低位宽减少显存与权重带宽，可提高 decode 吞吐和容纳更大 batch；但反量化内核、硬件支持和小 batch 会决定净收益。权重量化、激活量化与 KV 量化影响不同。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>对象</th><th>主要收益</th><th>主要风险</th></tr></thead><tbody><tr><td>权重</td><td>模型显存/带宽</td><td>少数通道误差、内核开销</td></tr><tr><td>激活</td><td>算子速度/通信</td><td>动态范围和校准</td></tr><tr><td>KV</td><td>长上下文并发/带宽</td><td>远距离检索与累积误差</td></tr></tbody></table></div><p>按任务、语言、长上下文、概率校准和工具参数切片回归，不能只看困惑度平均。后续“量化”页会深入方法，本页关注服务选择边界。</p><p>量化选择输入权重、激活或 KV、目标位宽、硬件内核和任务切片，输出低精度模型及显存、速度和质量差异。低位宽减少存储和带宽，反量化与校准又增加开销；更快只在支持良好且瓶颈匹配时成立。必须按语言、长上下文、工具参数和高风险任务回归。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>推测解码用并行验证减少串行步数<span class=\"dd-badge math\">推测</span></h2><p class=\"dd-lead\">小模型先猜 k 个 token，大模型怎样既加速又保持目标分布？</p><p>草稿模型快速提出一段，大模型一次前向并行评估多个位置，按接受/拒绝规则校正；正确算法保持目标模型分布。收益取决于草稿速度、k、接受率与验证批效率。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"推测解码每轮近似产出\"><mi>Edraft</mi><mo>≈</mo><mn>1</mn><mo>+</mo><mi>a</mi><mo>+</mo><msup><mi>a</mi><mn>2</mn></msup><mo>+</mo><mo>…</mo><mo>+</mo><msup><mi>a</mi><mi>k</mi></msup></math></div><p>a=.8、k=4 时约 1+.8+.64+.512+.4096=3.36 token/轮；但草稿和验证有成本，实际加速小于 3.36。领域错配、温度高或模型差异大时 a 低，反而变慢。</p><p>推测解码优化 TPOT/吞吐，不一定改善长输入 prefill；与流式结合时还要避免因验证批次造成可见输出突发抖动。</p><p>推测解码输入草稿模型、目标模型、草稿长度 k 和逐 token 接受率 a，输出经目标模型验证后的 token。草稿先并行提出，目标模型批量验证并按规则接受或校正；近似轮产出是 1+a+…+a^k。它不改变正确目标分布的前提是使用正确校正规则，低接受率或高验证成本会变慢。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>真实负载基准和质量门禁缺一不可<span class=\"dd-badge intuition\">评测</span></h2><p class=\"dd-lead\">离线单请求 tokens/s 提升 2 倍，怎样证明生产真的更好？</p><p>回放真实输入/输出长度联合分布、并发、到达突发、缓存命中和优先级；报告 TTFT/TPOT/E2E p50/p95/p99、吞吐、超时、KV/显存、功耗、每成功任务成本。做稳态、突发、过载和单节点故障。</p><p>任何量化、压缩 KV、上下文裁剪或近似解码都跑完整应用评测；所谓“质量不变”必须带切片与区间。内核和调度也可能产生数值错误、饥饿或公平问题。</p><div class=\"dd-note warn\"><b>基准作弊：</b>固定短输出、预热缓存、忽略排队、只报最佳 batch 和不计失败请求，会让结果无法迁移到生产。</div><p>生产基准输入真实长度分布、并发、突发、缓存命中、优先级和故障，输出延迟分位数、吞吐、资源、失败率、质量和每成功任务成本。固定负载做方案对照并覆盖稳态、过载和节点故障；只有平均 tokens/s 提升不能证明生产更好。任何算法或低精度变化都必须经过质量门禁。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">推理优化不是技巧清单，而是瓶颈诊断、约束选择和真实负载验证。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>prefill 和 decode 同样受限</td><td>前者常偏计算，后者常偏权重/KV 带宽</td></tr><tr><td>吞吐高就延迟低</td><td>组批可提高吞吐却增加排队和 p99</td></tr><tr><td>PagedAttention 减少 KV 数量</td><td>主要减少碎片并改善管理/共享</td></tr><tr><td>FlashAttention 是近似注意力</td><td>通过 IO 感知分块精确计算同一注意力</td></tr><tr><td>推测解码总能加速</td><td>接受率低或草稿/验证开销高会变慢</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>Transformer、self-attention、KV cache、GPU 内存层级</td></tr><tr><td><b>本页核心</b></td><td>TTFT/TPOT、roofline、连续批、KV 容量、推测解码</td></tr><tr><td>专项</td><td>量化、提示缓存、分布式推理、流式输出</td></tr><tr><td>生产</td><td>部署、模型路由、应用评测与可观测性</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>按请求阶段和长度切片测量</li><li>定位 compute/bandwidth/KV/queue 主因</li><li>选择内核/批处理/缓存/低精度方案</li><li>在受控负载做消融</li><li>真实并发压测尾延迟与过载</li><li>质量和每成功任务成本联合门禁</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>TTFT 与 TPOT 分别受什么影响？</li><li>为什么激进连续批 p99 可能变差？</li><li>32层示例单请求 8k KV 约多大？</li><li>推测示例每轮理想产出多少？</li><li>FlashAttention 解决什么？</li><li>假设“推理优化：先定位 prefill、decode、KV 还是排队瓶颈”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“推理优化：先定位 prefill、decode、KV 还是排队瓶颈”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>TTFT 含排队、上下文和 prefill；TPOT 主要反映逐 token decode 与调度。</li><li>等待组批、长 prefill 和调度竞争会增加尾部排队。</li><li>约 1.05GB，按给定 8 KV 头、128 维和 FP16。</li><li>a=.8、k=4 的独立近似约 3.36 token。</li><li>减少精确注意力计算的 HBM 中间读写，不解决所有排队/KV问题。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2205.14135\" target=\"_blank\" rel=\"noopener\">FlashAttention</a>：IO 感知精确注意力</li><li><a href=\"https://arxiv.org/abs/2309.06180\" target=\"_blank\" rel=\"noopener\">vLLM</a>：PagedAttention 与高吞吐服务</li><li><a href=\"https://www.usenix.org/conference/osdi22/presentation/yu\" target=\"_blank\" rel=\"noopener\">Orca</a>：迭代级调度与连续批处理</li><li><a href=\"https://arxiv.org/abs/2211.17192\" target=\"_blank\" rel=\"noopener\">Fast Inference from Transformers via Speculative Decoding</a>：保持目标分布的推测解码</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
